/* WTF Gyms branded transactional email.
   Brand pulled from live wtfgyms.com: primary red #D2000B, ink #0A0A0A, Inter.
   Each template is ONE line: Mailer::send() turns every \n into <br> before sending.
   Tables + inline styles: Outlook and Gmail discard <style> blocks.
   %CANDCATSURL% / %JBODCATSURL% now expand to bare URLs, so they are safe as hrefs. */
SET NAMES utf8mb4;

UPDATE email_template SET text = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f2f2f4;margin:0;padding:28px 12px;"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border:1px solid #e4e4e7;"><tr><td style="background:#0A0A0A;padding:22px 32px;"><img src="https://careers.wtfgyms.com/images/wtf-logo.png" width="132" height="46" alt="WTF" style="display:block;border:0;outline:none;text-decoration:none;width:132px;height:auto;" /></td></tr><tr><td style="height:4px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="padding:36px 32px 28px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><h1 style="margin:0 0 18px;font-size:24px;line-height:1.25;font-weight:700;color:#0A0A0A;">Thanks for applying, %CANDFIRSTNAME%</h1><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">We have received your application. It is now with the WTF hiring team.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="width:3px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td><td style="background:#fbf3f3;padding:15px 18px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><span style="font-size:16px;font-weight:700;color:#0A0A0A;">%JBODTITLE%</span></td></tr></table><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">Every application is read by a person. If your experience fits what the role needs, someone from our team will contact you on the number and email you gave us.</p><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">There is no need to apply again for the same role &mdash; a second application will not move you up the queue.</p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e4e4e7;padding:22px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><p style="margin:0 0 10px;font-size:12px;line-height:1.6;color:#76767c;">Automated message from the WTF Gyms careers portal. This address is not monitored, so please do not reply.</p><p style="margin:0;font-size:12px;line-height:1.6;color:#76767c;"><a href="https://careers.wtfgyms.com/careers/" style="color:#D2000B;text-decoration:none;font-weight:600;">All openings</a><span style="color:#c9c9cf;">&nbsp;&nbsp;|&nbsp;&nbsp;</span><a href="https://www.wtfgyms.com" style="color:#D2000B;text-decoration:none;font-weight:600;">wtfgyms.com</a></p></td></tr></table><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;"><tr><td style="padding:14px 32px;text-align:center;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;font-size:11px;color:#9a9aa0;">Witness the Fitness Private Limited &middot; Noida, Uttar Pradesh</td></tr></table></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_CANDIDATEAPPLY';
UPDATE email_template SET text = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f2f2f4;margin:0;padding:28px 12px;"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border:1px solid #e4e4e7;"><tr><td style="background:#0A0A0A;padding:22px 32px;"><img src="https://careers.wtfgyms.com/images/wtf-logo.png" width="132" height="46" alt="WTF" style="display:block;border:0;outline:none;text-decoration:none;width:132px;height:auto;" /></td></tr><tr><td style="height:4px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="padding:36px 32px 28px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><h1 style="margin:0 0 18px;font-size:24px;line-height:1.25;font-weight:700;color:#0A0A0A;">New application received</h1><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">%JBODOWNER%, a candidate has applied through the careers portal.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="width:3px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td><td style="background:#fbf3f3;padding:15px 18px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><span style="font-size:16px;font-weight:700;color:#0A0A0A;">%CANDFULLNAME%</span><br /><span style="font-size:14px;color:#3d3d42;">applied for %JBODTITLE%</span></td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 22px;"><tr><td style="background:#D2000B;"><a href="%CANDCATSURL%" style="display:inline-block;padding:13px 26px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;letter-spacing:.3px;">Open candidate in ATS</a></td></tr></table><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">Job order: <a href="%JBODCATSURL%" style="color:#D2000B;font-weight:600;">%JBODTITLE%</a></p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e4e4e7;padding:22px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><p style="margin:0 0 10px;font-size:12px;line-height:1.6;color:#76767c;">Automated notification from the WTF Gyms applicant tracking system.</p><p style="margin:0;font-size:12px;line-height:1.6;color:#76767c;"><a href="https://careers.wtfgyms.com/careers/" style="color:#D2000B;text-decoration:none;font-weight:600;">All openings</a><span style="color:#c9c9cf;">&nbsp;&nbsp;|&nbsp;&nbsp;</span><a href="https://www.wtfgyms.com" style="color:#D2000B;text-decoration:none;font-weight:600;">wtfgyms.com</a></p></td></tr></table><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;"><tr><td style="padding:14px 32px;text-align:center;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;font-size:11px;color:#9a9aa0;">Witness the Fitness Private Limited &middot; Noida, Uttar Pradesh</td></tr></table></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_CANDIDATEPORTALNEW';
UPDATE email_template SET text = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f2f2f4;margin:0;padding:28px 12px;"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#ffffff;border:1px solid #e4e4e7;"><tr><td style="background:#0A0A0A;padding:22px 32px;"><img src="https://careers.wtfgyms.com/images/wtf-logo.png" width="132" height="46" alt="WTF" style="display:block;border:0;outline:none;text-decoration:none;width:132px;height:auto;" /></td></tr><tr><td style="height:4px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="padding:36px 32px 28px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><h1 style="margin:0 0 18px;font-size:24px;line-height:1.25;font-weight:700;color:#0A0A0A;">Update on your application</h1><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">%CANDFULLNAME%, there is an update on your application with WTF Gyms.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 22px;"><tr><td style="width:3px;background:#D2000B;font-size:0;line-height:0;">&nbsp;</td><td style="background:#fbf3f3;padding:15px 18px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><span style="font-size:16px;font-weight:700;color:#0A0A0A;">%JBODTITLE%</span><br /><span style="font-size:14px;color:#3d3d42;">Status: %CANDSTATUS%</span></td></tr></table><p style="margin:0 0 15px;font-size:15px;line-height:1.65;color:#3d3d42;">%CANDSTATUSNOTES%</p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e4e4e7;padding:22px 32px;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;"><p style="margin:0 0 10px;font-size:12px;line-height:1.6;color:#76767c;">Automated message from the WTF Gyms careers portal. This address is not monitored, so please do not reply.</p><p style="margin:0;font-size:12px;line-height:1.6;color:#76767c;"><a href="https://careers.wtfgyms.com/careers/" style="color:#D2000B;text-decoration:none;font-weight:600;">All openings</a><span style="color:#c9c9cf;">&nbsp;&nbsp;|&nbsp;&nbsp;</span><a href="https://www.wtfgyms.com" style="color:#D2000B;text-decoration:none;font-weight:600;">wtfgyms.com</a></p></td></tr></table><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;"><tr><td style="padding:14px 32px;text-align:center;font-family:&#39;Inter&#39;,&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif;font-size:11px;color:#9a9aa0;">Witness the Fitness Private Limited &middot; Noida, Uttar Pradesh</td></tr></table></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_STATUSCHANGE';

SELECT tag, LENGTH(text) AS bytes FROM email_template WHERE tag IN ('EMAIL_TEMPLATE_CANDIDATEAPPLY','EMAIL_TEMPLATE_CANDIDATEPORTALNEW','EMAIL_TEMPLATE_STATUSCHANGE');
